// 1. Ambil payload dari Webhook (BUKAN MQTT lagi)
const raw = $input.first().json;
// Webhook mengirim data di dalam properti 'body'
const payload = raw.body || raw; 

const assetCode = payload.asset_code || '-';

// 2. Logika Cooldown 10 Menit (Anti-Spam)
const staticData = $getWorkflowStaticData('global');
const COOLDOWN_MS = 10 * 60 * 1000; 
const now = Date.now();
const lastSent = staticData[`last_sent_${assetCode}`] || 0;
const timeSinceLastSent = now - lastSent;

// Jika belum lewat 10 menit, HENTIKAN alur (jangan kirim notif)
if (timeSinceLastSent < COOLDOWN_MS) {
  return []; // Mencegah spam
}

// Jika lolos, catat waktu pengiriman
staticData[`last_sent_${assetCode}`] = now;

// 3. Ubah format waktu (ISO ke format Indonesia)
let lastSeenFormatted = payload.last_seen || '-';
if (lastSeenFormatted !== '-') {
  try {
    lastSeenFormatted = new Date(lastSeenFormatted).toLocaleString('id-ID', {
      timeZone: 'Asia/Jakarta',
      dateStyle: 'medium',
      timeStyle: 'short'
    }) + ' WIB';
  } catch (e) {
    // Jika format waktu error, biarkan pakai format asli
  }
}

// 4. Siapkan Teks untuk Fallback & Prompt AI
const messageFallback = `🔴 OFFLINE ALERT — ${payload.asset_name || '-'}\n\n📊 Status: OFFLINE\n⚠️ Severity: ${payload.severity || '-'}\n⏰ Terakhir Terlihat: ${lastSeenFormatted}\n\nℹ️ Notifikasi Standar (AI Gemini sedang limit/down)`;

const promptAI = `Kamu adalah AI Network Analyst profesional untuk sistem T-AIMS.
Perangkat berikut baru saja OFFLINE:
- Nama: ${payload.asset_name || '-'}
- Kode: ${assetCode}
- Kategori: ${payload.category || '-'}
- Severity: ${payload.severity || '-'}
- Terakhir terlihat: ${lastSeenFormatted}

Tugasmu:
1. Berikan analisis singkat (1-2 kalimat) kenapa perangkat ini bisa offline. Sesuaikan analisis dengan Kategori perangkat:
   - Jika CCTV: curigai koneksi jaringan (kabel LAN/Wi-Fi) terputus.
   - Jika Server: curigai service/database mati, atau overload CPU/RAM.
   - Jika Router/Switch/AP: curigai kabel jaringan putus, port mati, atau gangguan ISP.
   - Jika IoT: curigai baterai habis, modul Wi-Fi terputus, atau perangkat hang.
2. Berikan 1 rekomendasi tindakan cepat (troubleshooting).

Format output (WAJIB teks biasa, jangan JSON):
🔴 OFFLINE ALERT — ${payload.asset_name || '-'}

📊 Status: OFFLINE
⚠️ Severity: ${payload.severity || '-'}

🤖 Analisis AI:
[Analisis kamu di sini]

🎯 Tindakan:
[Rekomendasi kamu di sini]`;

// 5. Return data (TANPA kurung siku array agar Email tidak error)
return {
  json: {
    asset_code: assetCode,
    asset_name: payload.asset_name || '-',
    category: payload.category || '-',
    last_seen: lastSeenFormatted, 
    severity: payload.severity || 'unknown',
    message: messageFallback, 
    prompt_ai: promptAI       
  }
};
